/* Official workbook companion. This store never calls touch(), recordAnswer(), or markLesson(). */
PAGES.push('real');
const REAL_NAMES={vocab:'词汇',grammar:'语法',reading:'阅读',listening:'听力'};
const realPaper=id=>REAL_PAPERS.find(p=>p.id===id);
function realQuestions(p,scope='all'){return p.sections.flatMap(s=>s.groups.filter(g=>scope==='all'||scope===s.type||scope===g.id).flatMap(g=>g.questions.map(q=>({...q,type:s.type,group:g.id,groupTitle:g.title,groupNumber:g.number}))));}
const realEmpty=()=>({active:null,history:[]});
function cleanReal(raw){const out=realEmpty();if(!raw||typeof raw!=='object')return out;function session(s){const p=realPaper(s?.paper);if(!p||typeof s.scope!=='string'||!realQuestions(p,s.scope).length)return null;const valid=new Map(realQuestions(p,s.scope).map(q=>[q.id,q]));const answers={};for(const [id,a]of Object.entries(s.answers||{}))if(valid.has(id)&&Number.isInteger(a)&&a>=1&&a<=valid.get(id).options)answers[id]=a;return{paper:p.id,scope:s.scope,answers,flags:(Array.isArray(s.flags)?s.flags:[]).filter(id=>valid.has(id)),notes:String(s.notes||'').slice(0,4000),elapsed:num(s.elapsed,86400000),runningSince:Number.isFinite(s.runningSince)&&s.runningSince>0&&s.runningSince<=Date.now()?s.runningSince:null,budget:[0,20,30,40,60,90,115,140,155].includes(s.budget)?s.budget:0,section:['vocab','grammar','reading','listening'].includes(s.section)?s.section:realQuestions(p,s.scope)[0].type,date:dateValid(s.date)?s.date:dateKey()};}out.active=session(raw.active);out.history=(Array.isArray(raw.history)?raw.history:[]).slice(-100).map(x=>{const s=session(x);return s?{...s,runningSince:null,finished:dateValid(x.finished)?x.finished:s.date}:null;}).filter(Boolean);return out;}
let realState=realEmpty(),realSaveOK=true,realTab='topic',realYear=2018,realResult=-1,realReviewOnly=false;
try{realState=cleanReal(JSON.parse(localStorage.getItem('hajime-real-v1')||'null'));}catch{realSaveOK=false;}
function saveReal(){try{localStorage.setItem('hajime-real-v1',JSON.stringify(realState));}catch{realSaveOK=false;toast('真题记录未能保存，请导出备份。');}}
function realElapsed(s){return s.elapsed+(s.runningSince?Math.max(0,Date.now()-s.runningSince):0);}
function realClock(ms){const sec=Math.floor(ms/1000);return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}
function realPause(){const s=realState.active;if(s?.runningSince){s.elapsed=realElapsed(s);s.runningSince=null;saveReal();}}
function officialUrl(p,part){return `https://www.jlpt.jp/samples/sample${p.year}/pdf/${p.level}${{vocab:'V',grammar:'G',reading:'R',listening:'L',answer:'answer',script:'script'}[part]}.pdf`;}
function realLink(url,name){return `<a class="secondary real-link" href="${url}" target="_blank" rel="noopener">${name} ↗</a>`;}
function officialResources(p,type,result=false){const types=type?[type]:Object.keys(REAL_NAMES);return `<div class="official-resources"><strong>官方材料 · ${p.year} 版 ${p.level}</strong><div class="toolbar">${types.map(t=>realLink(officialUrl(p,t),`${REAL_NAMES[t]}题目 PDF`)).join('')}${result?realLink(officialUrl(p,'answer'),'官方答案表')+realLink(officialUrl(p,'script'),'听力原文'):''}${realLink('https://www.jlpt.jp/e/samples/sampleindex.html','官方材料目录')}</div>${types.includes('listening')?`<div class="official-audio"><small>听力请按大题顺序打开官方录音（新标签播放）：</small><div class="toolbar">${p.sections.find(s=>s.type==='listening').groups.map((g,i)=>realLink(`https://www.jlpt.jp/samples/sample${p.year}/mp3/${p.level}Q${i+1}.mp3`,`问题 ${i+1} · ${g.title}`)).join('')}</div></div>`:''}<small>题目与录音在 JLPT 官方网站打开；回到这里填写答题卡。听力示例不计分，N2 综合理解的 3(1)、3(2) 分开作答。</small></div>`;}
function realStats(s){const qs=realQuestions(realPaper(s.paper),s.scope),sections={};for(const [type,name]of Object.entries(REAL_NAMES)){const items=qs.filter(q=>q.type===type);if(items.length)sections[type]={name,total:items.length,answered:items.filter(q=>s.answers[q.id]).length,correct:items.filter(q=>s.answers[q.id]===q.answer).length};}return{total:qs.length,answered:qs.filter(q=>s.answers[q.id]).length,correct:qs.filter(q=>s.answers[q.id]===q.answer).length,sections};}
function startReal(scope){if(realState.active){toast('已有一份未交卷训练，先继续或交卷，再开始新的训练。');return;}const p=REAL_PAPERS.find(p=>p.year===realYear&&p.level===level);if(!p||!realQuestions(p,scope).length)return;const select=$('#realBudget');realState.active={paper:p.id,scope,answers:{},flags:[],notes:'',elapsed:0,runningSince:Date.now(),budget:Number(select?.value||0),section:realQuestions(p,scope)[0].type,date:dateKey()};realResult=-1;realReviewOnly=false;saveReal();render(false);}
function finishReal(){const s=realState.active;if(!s)return;realPause();realState.history.push({...s,answers:{...s.answers},flags:[...s.flags],finished:dateKey(),runningSince:null});realState.history=realState.history.slice(-100);realState.active=null;realResult=realState.history.length-1;realTab='history';saveReal();render(false);}
function realSetup(){const p=REAL_PAPERS.find(p=>p.year===realYear&&p.level===level),n=realQuestions(p).length;return `<div class="real-intro"><div><span class="label">OFFICIAL PRACTICE WORKBOOK</span><h2>真题训练，单独安排。</h2><p>从官方公开题目中查缺补漏。专题攻克一类题，整卷检验四项能力。</p><small>训练进度、错题与成绩独立保存，不计入每日任务。</small></div><div class="real-stat"><b>8</b><span>N5–N2 官方精选套卷<br>每级两册 · 2012 / 2018</span></div></div><div class="real-tabs" role="group" aria-label="真题训练模式">${[['topic','专题训练'],['full','整卷训练'],['history','训练记录']].map(([t,n])=>`<button class="chip ${realTab===t?'selected':''}" data-realtab="${t}">${n}</button>`).join('')}</div>${realTab==='history'?realHistory():`<div class="real-settings"><div><span>题目来源</span><div class="toolbar">${[2018,2012].map(y=>`<button class="chip ${y===realYear?'selected':''}" data-realyear="${y}">${y} 版官方问题集</button>`).join('')}</div></div><label>计时预算<select id="realBudget"><option value="0">自由练习 · 只记用时</option>${[20,30,40,60,90,115,140,155].map(n=>`<option value="${n}">${n} 分钟</option>`).join('')}</select></label></div><p class="completion-note">当前 ${level} · ${realYear} 版 · ${n} 道计分题。年份表示问题集出版年份；这是历次真题精选，非该年度单次考试原卷。计时预算可自选，不强制分段或自动交卷。</p>${realTab==='full'?`<div class="exam-banner"><div><span class="label">FULL WORKBOOK / ${level}</span><h2>${level} · ${realYear} 版整卷训练</h2><p>${p.sections.map(s=>`${REAL_NAMES[s.type]} ${s.groups.flatMap(g=>g.questions).length} 题`).join(' · ')}<br>保留原题顺序与题号，支持标记待查、暂停续答、交卷后核对。</p></div><button class="primary" data-realstart="all">开始整卷训练 →</button></div>${officialResources(p)}`:`<div class="real-topic-grid">${p.sections.map(s=>`<article><span class="label">${level} / ${s.type.toUpperCase()}</span><h2>${REAL_NAMES[s.type]}专题</h2><p>${s.groups.map(g=>g.title).join(' · ')}</p><button class="primary" data-realstart="${s.type}">训练全部 ${s.groups.flatMap(g=>g.questions).length} 题 →</button><details><summary>按题型单独练</summary>${s.groups.map(g=>`<button class="real-subtopic" data-realstart="${g.id}"><span>问题 ${g.number} · ${g.title}</span><b>${g.questions.length} 题 →</b></button>`).join('')}</details></article>`).join('')}</div>`}`}`;}
function realHistory(){return `<div class="sectionhead"><h2>独立训练记录 <small>${realState.history.length} 次</small></h2><button id="realExport">导出真题记录 ↗</button></div><div class="toolbar"><button class="secondary" id="realImport">导入真题记录 ↙</button></div>${realState.history.length?`<div class="real-history">${realState.history.map((s,i)=>{const st=realStats(s);return `<button data-realresult="${i}"><div><span class="label">${s.finished} · ${s.scope==='all'?'整卷':'专题'}</span><h3>${realPaper(s.paper).level} · ${realPaper(s.paper).year} 版</h3><p>${s.scope==='all'?'完整套卷':realQuestions(realPaper(s.paper),s.scope)[0].groupTitle+'等 · '+REAL_NAMES[realQuestions(realPaper(s.paper),s.scope)[0].type]} · 已答 ${st.answered}/${st.total} · 用时 ${realClock(s.elapsed)}</p></div><strong>${st.correct}<small> / ${st.total} 答对</small></strong><span>核对答案 →</span></button>`;}).reverse().join('')}</div>`:'<div class="empty-state">交卷后，这里会记录用时、正确率和待复习题号。提前交卷也保留，未答题单独标识。</div>'}`;}
function realSheet(){const s=realState.active,p=realPaper(s.paper),qs=realQuestions(p,s.scope),types=[...new Set(qs.map(q=>q.type))],st=realStats(s);if(!types.includes(s.section))s.section=types[0];return `<div class="real-session-head"><div><span class="label">${p.level} · ${p.year} 版 / ${s.scope==='all'?'整卷训练':'专题训练'}</span><h2>查看官方题目，在这里作答。</h2><p>已答 <b id="realAnswered">${st.answered}</b> / ${st.total} · 标记待查 ${s.flags.length} 题</p></div><div class="real-clock-box"><b id="realClock">${realClock(realElapsed(s))}</b><small id="realTimeStatus">${s.runningSince?'计时中':'已暂停'}${s.budget?` · 预算 ${s.budget} 分钟`:' · 自由练习'}</small><button class="secondary" id="realPause">${s.runningSince?'暂停计时':'继续计时'}</button></div></div><div class="real-controls"><div class="toolbar">${types.map(t=>`<button class="chip ${s.section===t?'selected':''}" data-realsection="${t}">${REAL_NAMES[t]} ${qs.filter(q=>q.type===t&&s.answers[q.id]).length}/${qs.filter(q=>q.type===t).length}</button>`).join('')}</div><button class="primary" id="realSubmit">交卷并核对 →</button></div>${officialResources(p,s.section)}<div class="hint">答题会自动保存。切换本站其他页面时暂停计时；回到真题训练后可继续。提交前可以修改选项或清除答案。<span id="realSaveStatus" role="status">${realSaveOK?'已保存在当前浏览器':'保存不可用，请导出备份'}</span></div><div class="answer-sheet">${p.sections.find(x=>x.type===s.section).groups.filter(g=>s.scope==='all'||s.scope===s.section||s.scope===g.id).map(g=>`<section><div class="sectionhead"><h3>问题 ${g.number} · ${g.title}</h3><span>${g.questions.length} 题</span></div><div class="answer-grid">${g.questions.map(q=>`<div class="answer-item ${s.answers[q.id]?'answered':''} ${s.flags.includes(q.id)?'flagged':''}"><strong>第 ${q.label} 题</strong><div class="real-choices" role="group" aria-label="${REAL_NAMES[s.section]}第 ${q.label} 题">${Array.from({length:q.options},(_,i)=>`<button data-realanswer="${q.id}" data-value="${i+1}" aria-pressed="${s.answers[q.id]===i+1}" class="${s.answers[q.id]===i+1?'chosen':''}">${i+1}</button>`).join('')}</div><div class="answer-tools"><button data-realflag="${q.id}" aria-pressed="${s.flags.includes(q.id)}">${s.flags.includes(q.id)?'★ 已标记':'☆ 待查'}</button><button data-realclear="${q.id}" aria-label="清除${REAL_NAMES[s.section]}第${q.label}题答案">清除</button></div></div>`).join('')}</div></section>`).join('')}</div><label class="real-notes">本次训练笔记<textarea id="realNotes" maxlength="4000" placeholder="记下不熟悉的题号、词汇或解题思路…">${esc(s.notes)}</textarea></label><div class="toolbar"><button class="primary" id="realSubmitBottom">交卷并核对 →</button><button class="secondary" id="realExport">导出真题记录 ↗</button></div><dialog id="realSubmitDialog"><h2>确认交卷</h2><p>已答 ${st.answered} / ${st.total} 题；${st.total-st.answered} 题未答。交卷后显示正确答案，本次答题卡将归档。</p><div class="toolbar"><button class="secondary" id="realContinue">继续作答</button><button class="primary" id="realFinish">确认交卷</button></div></dialog>`;}
function realResultView(){const s=realState.history[realResult];if(!s){realResult=-1;return realHistory();}const p=realPaper(s.paper),st=realStats(s),qs=realQuestions(p,s.scope).filter(q=>!realReviewOnly||s.answers[q.id]!==q.answer||s.flags.includes(q.id));return `<div class="real-result-head"><div><span class="label">${p.level} · ${p.year} 版 · ${s.scope==='all'?'整卷':'专题'} / ${s.finished}</span><h2>本次训练结果</h2><p>答对 ${st.correct} / ${st.total} · 已答 ${st.answered} · 未答 ${st.total-st.answered} · 用时 ${realClock(s.elapsed)}</p></div><strong>${Math.round(st.correct/st.total*100)}<small>% 正确率</small></strong></div><div class="result-sections">${Object.values(st.sections).map(x=>`<div class="stat"><b>${x.correct}<span> / ${x.total}</span></b><span>${x.name} · 已答 ${x.answered}</span></div>`).join('')}</div><div class="hint">这是答对题数的比例，未答题不计正确；不是 JLPT 标准分，也不用于判定考试合格。本站提供答案核对，题目解读请结合官方原文与教材。</div>${officialResources(p,null,true)}<div class="toolbar"><button class="primary" id="realBack">返回真题训练 →</button><button class="secondary" id="realReviewToggle">${realReviewOnly?'查看全部题号':'只看错题、未答与标记'}</button><button class="secondary" data-realretry="${s.paper}" data-scope="${s.scope}" ${realState.active?'disabled':''}>再练一次 →</button><button class="secondary" id="realExport">导出真题记录 ↗</button></div><div class="real-result-table"><table><thead><tr><th>专题 / 题型</th><th>题号</th><th>我的答案</th><th>正确答案</th><th>核对</th></tr></thead><tbody>${qs.map(q=>`<tr class="${s.answers[q.id]===q.answer?'real-correct':'real-wrong'}"><td>${REAL_NAMES[q.type]} · ${q.groupTitle}</td><td>${q.label}</td><td>${s.answers[q.id]||'未答'}</td><td>${q.answer}</td><td>${s.answers[q.id]===q.answer?'✓ 正确':s.answers[q.id]?'✕ 错误':'○ 未答'}${s.flags.includes(q.id)?' · ★ 待查':''}</td></tr>`).join('')}</tbody></table></div>${s.notes?`<div class="hint"><strong>训练笔记</strong><p class="saved-real-notes">${esc(s.notes)}</p></div>`:''}${!qs.length?'<div class="empty-state">没有错题、未答或待查题目。</div>':''}`;}
function renderReal(){return title('OFFICIAL QUESTIONS · INDEPENDENT PRACTICE','真题训练','专题查缺补漏，整卷集中训练。独立于每日学习计划。')+`<section class="container page-section">${realResult>=0?realResultView():realState.active?realSheet():realSetup()}<details class="learning-help"><summary>题目来源</summary><p class="real-source">材料来源：${realLink('https://www.jlpt.jp/e/samples/sampleindex.html','JLPT 官方公开问题集')} · Source: Official Worldwide Japanese-Language Proficiency Test Website (https://www.jlpt.jp/)。题目、答案 PDF 与录音均链接到官方来源；本站保留答题与核对记录。</p></details><input id="realImportFile" type="file" accept="application/json,.json" hidden></section>`;}
const renderBeforeReal=render;
render=function(scroll=true){if(page!=='real'){realPause();renderBeforeReal(scroll);return;}guideActive=false;if(realState.active)level=realPaper(realState.active.paper).level;stopAudio();$('#view').innerHTML=compactLearningNotes(renderReal());$('#levelTabs').innerHTML=LEVELS.map(l=>`<button data-level="${l}" class="${level===l?'selected':''}" aria-pressed="${level===l}" ${realState.active&&l!==level?'disabled':''}>${l}</button>`).join('');document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(scroll)window.scrollTo({top:0,behavior:'instant'});};
function updateRealTime(){if(page!=='real'||!realState.active||!$('#realClock'))return;const s=realState.active,ms=realElapsed(s);$('#realClock').textContent=realClock(ms);$('#realTimeStatus').textContent=s.budget&&ms>=s.budget*60000?'预算时间已到，可以交卷或继续练习':`${s.runningSince?'计时中':'已暂停'}${s.budget?` · 预算 ${s.budget} 分钟`:' · 自由练习'}`;}
setInterval(updateRealTime,1000);
window.addEventListener('pagehide',realPause);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;
 if(d.level&&page==='real'&&!realState.active){realResult=-1;render(false);}
 if(d.realtab){realTab=d.realtab;realResult=-1;render(false);}if(d.realyear){realYear=Number(d.realyear);render(false);}if(d.realstart)startReal(d.realstart);
 if(d.realsection&&realState.active){realState.active.section=d.realsection;saveReal();render(false);}
 if(d.realanswer&&realState.active){const s=realState.active,q=realQuestions(realPaper(s.paper),s.scope).find(q=>q.id===d.realanswer),a=Number(d.value);if(!q||a<1||a>q.options)return;s.answers[q.id]=a;saveReal();const item=b.closest('.answer-item');item.classList.add('answered');item.querySelectorAll('[data-realanswer]').forEach(x=>{x.classList.toggle('chosen',x===b);x.setAttribute('aria-pressed',String(x===b));});$('#realAnswered').textContent=Object.keys(s.answers).length;$('#realSaveStatus').textContent=realSaveOK?'答案已自动保存':'保存不可用，请导出备份';}
 if(d.realflag&&realState.active){const s=realState.active;s.flags=s.flags.includes(d.realflag)?s.flags.filter(x=>x!==d.realflag):[...s.flags,d.realflag];saveReal();render(false);}if(d.realclear&&realState.active){delete realState.active.answers[d.realclear];saveReal();render(false);}
 if(b.id==='realPause'&&realState.active){if(realState.active.runningSince)realPause();else{realState.active.runningSince=Date.now();saveReal();}render(false);}
 if(b.id==='realSubmit'||b.id==='realSubmitBottom'){const st=realStats(realState.active);$('#realSubmitDialog p').textContent=`已答 ${st.answered} / ${st.total} 题；${st.total-st.answered} 题未答。交卷后显示正确答案，本次答题卡将归档。`;$('#realSubmitDialog').showModal();}
 if(b.id==='realContinue')$('#realSubmitDialog').close();if(b.id==='realFinish')finishReal();
 if(d.realresult!==undefined){realResult=Number(d.realresult);realReviewOnly=false;render(false);}if(b.id==='realReviewToggle'){realReviewOnly=!realReviewOnly;render(false);}if(b.id==='realBack'){realResult=-1;realTab='history';render(false);}
 if(d.realretry&&!realState.active){const p=realPaper(d.realretry);realYear=p.year;level=p.level;realResult=-1;startReal(d.scope);}
 if(b.id==='realExport'){const snapshot=cleanReal(realState);if(snapshot.active){snapshot.active.elapsed=realElapsed(realState.active);snapshot.active.runningSince=null;}const a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify({type:'hajime-real-v1',...snapshot},null,2)],{type:'application/json'}));a.href=u;a.download=`初见日语-真题记录-${dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
 if(b.id==='realImport')$('#realImportFile').click();
});
document.addEventListener('input',e=>{if(e.target.id==='realNotes'&&realState.active){realState.active.notes=e.target.value;saveReal();}});
document.addEventListener('change',async e=>{if(e.target.id!=='realImportFile')return;const file=e.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error();const raw=JSON.parse(await file.text());if(raw.type!=='hajime-real-v1')throw Error();const incoming=cleanReal(raw);if(incoming.active?.runningSince){incoming.active.elapsed=realElapsed(incoming.active);incoming.active.runningSince=null;}if(!realState.active)realState.active=incoming.active;realState.history=[...new Map([...realState.history,...incoming.history].map(s=>[JSON.stringify(s),s])).values()].slice(-100);saveReal();realResult=-1;render(false);toast('真题记录已合并；当前未交卷训练优先保留。');}catch{toast('导入失败：请选择本站导出的真题记录 JSON。');}});
fromHash();
